<?php
namespace Tests\Feature;use App\Models\Company;use App\Models\Segment;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Laravel\Sanctum\Sanctum;use Tests\TestCase;class CompanyTest extends TestCase{    use RefreshDatabase;    protected function setUp(): void    {        parent::setUp();        $this->user = User::factory()->create();        Sanctum::actingAs($this->user, ["*"]);        $this->companyData = [            "corporate_name" => "Empresa Teste Ltda",            "trade_name" => "Empresa Teste",            "tax_id" => "12345678000190",            "segment_id" => Segment::factory()->create()->id,            "owner_id" => $this->user->id,            "city" => "São Paulo",            "state" => "SP",            "status" => "prospecting",        ];    }    /**     * Teste: listar empresas com sucesso (index).     */    public function test_list_companies_success(): void    {        foreach (range(1, 3) as $i) {            $this->createCompany([                "corporate_name" => "Empresa {$i} Ltda",                "trade_name" => "Empresa {$i}",                "tax_id" => "123456780001" . str_pad($i, 2, "0", STR_PAD_LEFT),                "status" => "prospecting",            ]);        }        $response = $this->get("/api/v1/companies");        $response->assertStatus(200);        $response->assertJson([            "success" => true,            "status" => 200,        ]);        $response->assertJsonStructure([            "data" => [                "items",                "pagination",            ],            "message",            "status",        ]);    }    /**     * Teste: buscar empresa por ID com sucesso (show).     */    public function test_show_company_success(): void    {        $company = $this->createCompany([            "corporate_name" => "Empresa para Buscar Ltda",            "trade_name" => "Empresa para Buscar",            "tax_id" => "11222333000190",            "status" => "prospecting",        ]);        $response = $this->get("/api/v1/companies/{$company->id}");        $response->assertStatus(200);        $response->assertJson([            "success" => true,            "status" => 200,            "message" => "Empresa encontrada.",        ]);        $response->assertJsonStructure([            "data" => [                "id",                "corporate_name",                "trade_name",                "tax_id",                "status",            ],            "message",            "status",        ]);    }    /**     * Teste: buscar empresa inexistente retorna 404.     */    public function test_show_company_not_found(): void    {        $response = $this->get("/api/v1/companies/99999");        $response->assertStatus(404);        $response->assertJson([            "success" => false,            "status" => 404,        ]);    }    /**     * Teste: criar empresa com sucesso (store).     */    public function test_store_company_success(): void    {        $response = $this->post("/api/v1/companies", $this->companyData);        $response->assertStatus(201);        $response->assertJson([            "success" => true,            "status" => 201,            "message" => "Empresa criada com sucesso.",        ]);        $response->assertJsonStructure([            "data" => [                "id",                "corporate_name",                "trade_name",                "tax_id",                "status",            ],            "message",            "status",        ]);        $this->assertDatabaseHas("companies", [            "corporate_name" => "Empresa Teste Ltda",            "tax_id" => "12345678000190",        ]);    }    /**     * Teste: criar empresa com dados inválidos retorna erro de validação.     */    public function test_store_company_validation_error(): void    {        $invalidData = [            "corporate_name" => "",            "status" => "",        ];        $response = $this->post("/api/v1/companies", $invalidData);        $response->assertStatus(422);        $response->assertJsonValidationErrors([            "corporate_name",            "status",        ]);    }    /**     * Teste: atualizar empresa com sucesso (update).     */    public function test_update_company_success(): void    {        $company = $this->createCompany([            "corporate_name" => "Empresa Original Ltda",            "trade_name" => "Empresa Original",            "tax_id" => "11222333000190",            "status" => "prospecting",        ]);        $updateData = [            "trade_name" => "Empresa Atualizada",            "status" => "churned",        ];        $response = $this->put("/api/v1/companies/{$company->id}", $updateData);        $response->assertStatus(200);        $response->assertJson([            "success" => true,            "message" => "Empresa atualizada com sucesso.",        ]);        $this->assertDatabaseHas("companies", [            "id" => $company->id,            "trade_name" => "Empresa Atualizada",        ]);    }    /**     * Teste: atualizar empresa inexistente retorna 404.     */    public function test_update_company_not_found(): void    {        $response = $this->put("/api/v1/companies/99999", [            "trade_name" => "Novo Nome",        ]);        $response->assertStatus(404);        $response->assertJson([            "success" => false,            "status" => 404,        ]);    }    /**     * Teste: excluir empresa com sucesso (destroy).     */    public function test_destroy_company_success(): void    {        $company = $this->createCompany([            "corporate_name" => "Empresa para Excluir Ltda",            "trade_name" => "Empresa para Excluir",            "tax_id" => "11222333000190",            "status" => "prospecting",        ]);        $response = $this->delete("/api/v1/companies/{$company->id}");        $response->assertStatus(200);        $response->assertJson([            "success" => true,            "message" => "Empresa removida com sucesso.",        ]);        $this->assertSoftDeleted("companies", [            "id" => $company->id,        ]);    }    /**     * Teste: excluir empresa inexistente retorna 404.     */    public function test_destroy_company_not_found(): void    {        $response = $this->delete("/api/v1/companies/99999");        $response->assertStatus(404);        $response->assertJson([            "success" => false,            "status" => 404,        ]);    }    /**     * Teste: rota sem autenticação retorna 401.     */    public function test_unauthenticated_request_returns_401(): void    {                $this->app['auth']->forgetGuards();

        $response = $this->get("/api/v1/companies");        $response->assertStatus(401);    }}